async function inserir() {
  // Apagar questoes dos exames 38-44 existentes
  await supabase.from('oab_questoes').delete()
    .in('exame', ['38','39','40','41','42','43','44'])
  
  // Inserir em lotes de 50
  let total = 0
  for (let i = 0; i < questoes.length; i += 50) {
    const lote = questoes.slice(i, i + 50)
    const { error } = await supabase.from('oab_questoes').insert(lote)
    if (error) {
      console.error('Erro no lote', i, error.message)
    } else {
      total += lote.length
      console.log(`Inseridas ${total}/${questoes.length} questões`)
    }
  }
  console.log('Concluído!')
}

inserir().catch(console.error)
